package com.lzx.smartmes.integration.service;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lzx.smartmes.integration.dto.ErpOrderDTO;import com.lzx.smartmes.integration.mapper.ProductRefMapper;import com.lzx.smartmes.production.entity.ProductionOrder;import com.lzx.smartmes.production.mapper.ProductionOrderMapper;import org.junit.jupiter.api.Test;class ErpOrderServiceTest{@Test void duplicateErpOrderReturnsExisting(){ProductionOrderMapper om=mock(ProductionOrderMapper.class);ProductRefMapper pm=mock(ProductRefMapper.class);ProductionOrder old=new ProductionOrder();old.setErpOrderNo("ERP-1");when(om.selectOne(any())).thenReturn(old);ErpOrderDTO d=new ErpOrderDTO();d.setErpOrderNo("ERP-1");assertSame(old,new ErpOrderService(om,pm).receive(d));verify(om,never()).insert(any(ProductionOrder.class));}}
